import { z } from 'zod';

/**
 * Metric Provenance Labels as defined in LOADOUT Version 2 Source of Truth (Sec. 10.3).
 *
 * - measured: Directly observed through a documented supported browser API (e.g., performance.now()).
 * - estimated: Calculated from an explicit model, heuristic, or assumption (e.g., DOM node formula).
 * - simulated: Generated by a synthetic workload, fake timer, or synthetic event generator.
 * - inferred: Reasoned conclusion derived from multi-signal evidence (e.g., suspected bottleneck).
 * - unavailable: Observable in principle, but cannot be collected in this specific environment (e.g., window.performance.memory on Firefox/WebKit).
 * - unsupported: Capability is not implemented by the platform or product (e.g., direct GPU memory access).
 */
export type MetricProvenance =
  'measured' | 'estimated' | 'simulated' | 'inferred' | 'unavailable' | 'unsupported';

export const METRIC_PROVENANCES: readonly MetricProvenance[] = [
  'measured',
  'estimated',
  'simulated',
  'inferred',
  'unavailable',
  'unsupported',
] as const;

export const metricProvenanceSchema = z.enum([
  'measured',
  'estimated',
  'simulated',
  'inferred',
  'unavailable',
  'unsupported',
]);

/**
 * A value wrapped with its provenance metadata, collection method, and optional caveats.
 * Enforces the core principle: "Transparent provenance: distinguish measured, estimated, simulated, inferred, and unsupported values."
 */
export interface ProvenancedValue<T> {
  value: T;
  provenance: MetricProvenance;
  method: string;
  notes?: string;
}

export function createProvenancedValue<T>(
  value: T,
  provenance: MetricProvenance,
  method: string,
  notes?: string,
): ProvenancedValue<T> {
  return { value, provenance, method, ...(notes ? { notes } : {}) };
}

export function isMeasured<T>(metric: ProvenancedValue<T>): boolean {
  return metric.provenance === 'measured';
}

export function isEstimated<T>(metric: ProvenancedValue<T>): boolean {
  return metric.provenance === 'estimated';
}

export function isSimulated<T>(metric: ProvenancedValue<T>): boolean {
  return metric.provenance === 'simulated';
}

export function isInferred<T>(metric: ProvenancedValue<T>): boolean {
  return metric.provenance === 'inferred';
}

export const provenancedValueSchema = <T extends z.ZodTypeAny>(valueSchema: T) =>
  z.object({
    value: valueSchema,
    provenance: metricProvenanceSchema,
    method: z.string().min(1),
    notes: z.string().optional(),
  });

/**
 * Optional granular timing breakdown across benchmark phases (Sec. 10.2).
 */
export interface PhaseTimings {
  setupMs?: number;
  parseMs?: number;
  processMs?: number;
  renderMs?: number;
  cleanupMs?: number;
  totalMs: number;
}

export const phaseTimingsSchema = z.object({
  setupMs: z.number().nonnegative().optional(),
  parseMs: z.number().nonnegative().optional(),
  processMs: z.number().nonnegative().optional(),
  renderMs: z.number().nonnegative().optional(),
  cleanupMs: z.number().nonnegative().optional(),
  totalMs: z.number().nonnegative(),
});

/**
 * Single benchmark trial iteration (both warm-up and measured repetitions).
 * Individual run values must always be preserved for statistical reproducibility.
 */
export interface BenchmarkTrial {
  iteration: number;
  isWarmup: boolean;
  durationMs: number;
  phaseTimings?: PhaseTimings;
  domNodes?: number;
  heapBytesUsed?: number;
  timestamp: number;
  error?: string;
}

export const benchmarkTrialSchema = z.object({
  iteration: z.number().int().nonnegative(),
  isWarmup: z.boolean(),
  durationMs: z.number().nonnegative(),
  phaseTimings: phaseTimingsSchema.optional(),
  domNodes: z.number().int().nonnegative().optional(),
  heapBytesUsed: z.number().int().nonnegative().optional(),
  timestamp: z.number().nonnegative(),
  error: z.string().optional(),
});

/**
 * Aggregated statistical distribution of measured trials (excluding warm-ups).
 * Per SoT Sec 10.2: "Report median and spread; use percentiles when sample size supports interpretation."
 */
export interface BenchmarkDistribution {
  sampleCount: number;
  warmupCount: number;
  medianMs: number;
  meanMs: number;
  minMs: number;
  maxMs: number;
  spreadMs: number;
  standardDeviationMs: number;
  p95Ms?: number;
  p99Ms?: number;
  trials: BenchmarkTrial[];
  /** Optional warnings about sample size confidence, high variance, or tail-latency reliability */
  warnings?: string[];
}

export const benchmarkDistributionSchema = z.object({
  sampleCount: z.number().int().nonnegative(),
  warmupCount: z.number().int().nonnegative(),
  medianMs: z.number().nonnegative(),
  meanMs: z.number().nonnegative(),
  minMs: z.number().nonnegative(),
  maxMs: z.number().nonnegative(),
  spreadMs: z.number().nonnegative(),
  standardDeviationMs: z.number().nonnegative(),
  p95Ms: z.number().nonnegative().optional(),
  p99Ms: z.number().nonnegative().optional(),
  trials: z.array(benchmarkTrialSchema),
  warnings: z.array(z.string()).optional(),
});

/**
 * Output Correctness Gates (Sec. 10.5).
 * "A faster candidate that changes output unexpectedly is not a valid optimization."
 */
export type CorrectnessStatus = 'passed' | 'failed' | 'unchecked';

export const correctnessStatusSchema = z.enum(['passed', 'failed', 'unchecked']);

export interface CorrectnessGateResult {
  status: CorrectnessStatus;
  recordCountParity: boolean;
  schemaParity: boolean;
  sampleHashParity?: boolean;
  nullSemanticsPreserved: boolean;
  orderPreserved?: boolean;
  divergenceDetails?: string[];
}

export const correctnessGateResultSchema = z.object({
  status: correctnessStatusSchema,
  recordCountParity: z.boolean(),
  schemaParity: z.boolean(),
  sampleHashParity: z.boolean().optional(),
  nullSemanticsPreserved: z.boolean(),
  orderPreserved: z.boolean().optional(),
  divergenceDetails: z.array(z.string()).optional(),
});

/**
 * Runtime environment and hardware capability metadata (Sec. 10.2 & 10.6).
 */
export interface BenchmarkEnvironment {
  userAgent: string;
  platform: string;
  hardwareConcurrency?: number;
  deviceMemoryGb?: number;
  browserEngine: string;
  jsRuntime: string;
  capturedAt: string;
}

export const benchmarkEnvironmentSchema = z.object({
  userAgent: z.string().min(1),
  platform: z.string().min(1),
  hardwareConcurrency: z.number().int().positive().optional(),
  deviceMemoryGb: z.number().positive().optional(),
  browserEngine: z.string().min(1),
  jsRuntime: z.string().min(1),
  capturedAt: z.string().datetime(),
});

/**
 * Reproducible benchmark execution policy and parameters.
 */
export interface BenchmarkPolicy {
  warmupIterations: number;
  measuredIterations: number;
  timeoutMsPerIteration: number;
  cooldownMsBetweenIterations: number;
}

export const benchmarkPolicySchema = z.object({
  warmupIterations: z.number().int().nonnegative(),
  measuredIterations: z.number().int().positive(),
  timeoutMsPerIteration: z.number().int().positive(),
  cooldownMsBetweenIterations: z.number().int().nonnegative(),
});

export const DEFAULT_BENCHMARK_POLICY: BenchmarkPolicy = {
  warmupIterations: 2,
  measuredIterations: 5,
  timeoutMsPerIteration: 5000,
  cooldownMsBetweenIterations: 16,
};

/**
 * Comparison Verdict between Baseline and Candidate.
 * Distinguishes genuine improvements from noise and invalid runs (Sec. 10.4).
 */
export type ComparisonVerdict =
  'improved' | 'regressed' | 'no-difference' | 'inconclusive' | 'invalid';

export const comparisonVerdictSchema = z.enum([
  'improved',
  'regressed',
  'no-difference',
  'inconclusive',
  'invalid',
]);

/**
 * Result data for a single benchmarked variant (baseline or candidate).
 */
export interface BenchmarkVariantRun {
  variantId: string;
  variantLabel: string;
  distribution: BenchmarkDistribution;
  domNodeCount: ProvenancedValue<number>;
  estimatedMemoryBytes?: ProvenancedValue<number>;
  observedMemoryBytes?: ProvenancedValue<number>;
}

export const benchmarkVariantRunSchema = z.object({
  variantId: z.string().min(1),
  variantLabel: z.string().min(1),
  distribution: benchmarkDistributionSchema,
  domNodeCount: provenancedValueSchema(z.number().int().nonnegative()),
  estimatedMemoryBytes: provenancedValueSchema(z.number().int().nonnegative()).optional(),
  observedMemoryBytes: provenancedValueSchema(z.number().int().nonnegative()).optional(),
});

/**
 * Full Canonical Comparison Record between Baseline and Candidate.
 * The foundational data structure for reports, persistence, and AI interpretation.
 */
export interface BenchmarkComparisonRecord {
  id: string;
  workloadId: string;
  workloadName: string;
  workloadFingerprint: string;
  environment: BenchmarkEnvironment;
  policy: BenchmarkPolicy;
  baseline: BenchmarkVariantRun;
  candidate: BenchmarkVariantRun;
  correctness: CorrectnessGateResult;
  verdict: ComparisonVerdict;
  verdictReason: string;
  delta: {
    medianDurationMs: number;
    medianDurationChangePct: number;
    domNodesDelta: number;
    domNodesChangePct: number;
  };
  warnings: string[];
  createdAt: string;
}

export const benchmarkComparisonRecordSchema = z.object({
  id: z.string().min(1),
  workloadId: z.string().min(1),
  workloadName: z.string().min(1),
  workloadFingerprint: z.string().min(1),
  environment: benchmarkEnvironmentSchema,
  policy: benchmarkPolicySchema,
  baseline: benchmarkVariantRunSchema,
  candidate: benchmarkVariantRunSchema,
  correctness: correctnessGateResultSchema,
  verdict: comparisonVerdictSchema,
  verdictReason: z.string(),
  delta: z.object({
    medianDurationMs: z.number(),
    medianDurationChangePct: z.number(),
    domNodesDelta: z.number(),
    domNodesChangePct: z.number(),
  }),
  warnings: z.array(z.string()),
  createdAt: z.string().datetime(),
});

/**
 * Validation helper function with strict schema parsing.
 */
export function validateBenchmarkComparisonRecord(data: unknown): BenchmarkComparisonRecord {
  return benchmarkComparisonRecordSchema.parse(data) as BenchmarkComparisonRecord;
}

export function safeValidateBenchmarkComparisonRecord(data: unknown) {
  return benchmarkComparisonRecordSchema.safeParse(data);
}
